  function slotUsage(ids=state.installedEquipment){const used={light:0,medium:0,heavy:0};for(const id of ids){const item=EQUIPMENT[id];if(item)used[item.slotType]+=item.slots;}return used;}
  function equipmentFits(ship,extraId=null){const ids=[...state.installedEquipment];if(extraId&&!ids.includes(extraId))ids.push(extraId);const used=slotUsage(ids);return SLOT_TYPES.every(type=>used[type]<=(ship.slots[type]||0));}
  function slotSummary(ship=vessel(),usage=slotUsage()){return SLOT_TYPES.map(type=>`${type[0].toUpperCase()}${type.slice(1)} ${usage[type]}/${ship.slots[type]}`).join(' · ');}
  function payroll(){return state.scientists.reduce((sum,item)=>sum+CAREERS[item.career].salary,0);}
  function averageQuality(){if(!state.scientists.length)return .7;return state.scientists.reduce((sum,item)=>sum+CAREERS[item.career].quality,0)/state.scientists.length;}
  function hasSpecialty(ids){return ids.some(id=>state.scientists.some(scientist=>scientist.specialty===id));}
  function equipmentOperational(id){
    const item=EQUIPMENT[id];if(!item||!state.installedEquipment.includes(id))return false;
    const needs=[];for(const requirement of item.crew||[])for(let count=0;count<(requirement.count||1);count++)needs.push(requirement);
    needs.sort((a,b)=>CAREERS[b.minCareer].level-CAREERS[a.minCareer].level);
    const scientists=state.scientists;
    const assign=(index,used)=>{if(index>=needs.length)return true;const need=needs[index],level=CAREERS[need.minCareer].level;for(let i=0;i<scientists.length;i++){const scientist=scientists[i];if(used.has(i)||CAREERS[scientist.career].level<level||!need.specialties.includes(scientist.specialty))continue;used.add(i);if(assign(index+1,used))return true;used.delete(i);}return false;};
    return assign(0,new Set());
  }
  function hasEquipment(ids){return ids.some(id=>equipmentOperational(id));}
  function eligible(template){return hasSpecialty(template.specialties)&&hasEquipment(template.equipment);}
