  function enterPort(port,options={}){state.port={name:port.name,lat:port.lat,lon:port.lon};if(!options.resume){state.portVisits++;activePortTab='resupply';portScrollTop=0;portTabsScrollLeft=0;generateCandidates(state.port);generateOffers(state.port);}renderSidebar();renderPort();}
